const roleOf=()=>roles[state.background]||roles.Student;
function onboarding(){
 const s=step,attaching=studentSetupMode==='attach',total=attaching?1:3;
 $('stepCount').textContent=String(s+1).padStart(2,'0')+' / '+String(total).padStart(2,'0');$('stepBar').style.width=((s+1)/total*100)+'%';$('backStep').style.visibility=s&&!attaching?'visible':'hidden';$('nextStep').textContent=attaching?'Start introduction at campus':s===2?'Begin my ChinaLife':'Continue';
 let h='<span class="eyebrow">SEASON 0 · YOUR LIFE IN CHINA</span>';
 if(s===0)h+='<div class="onboard-title">Where are you starting your ChinaLife?</div><p class="onboard-subtitle">You don’t play ChinaLife. You live it.</p><div class="choice-grid">'+[['inside','I’m already in China 🇨🇳'],['outside','I’m outside China 🌍']].map(([id,label])=>'<button type="button" class="choice '+(onboard.start===id?'selected':'')+'" data-start="'+id+'"><b>'+label+'</b></button>').join('')+'</div>';
 if(s===1)h+='<div class="onboard-title">Who are you in China?</div><p class="onboard-subtitle">Your role shapes your phone, your goals and where you begin.</p><div class="choice-grid">'+Object.entries(roles).map(([id,r])=>'<button type="button" class="choice '+(onboard.role===id?'selected':'')+'" data-role="'+id+'"><b>'+r.icon+' '+r.label+'</b><span>'+r.pitch+'</span></button>').join('')+'</div>';
 if(s===2){
  const pick=(key,items,current)=>'<div class="trait-grid">'+items.map(([value,label,swatch])=>'<button type="button" class="trait '+(current===value?'selected':'')+'" data-'+key+'="'+value+'">'+(swatch?'<b style="color:'+value+'">●</b> ':'')+label+'</button>').join('')+'</div>';
  h+='<div class="onboard-title">Build your character</div>'+(accountName?'<label>Hafrik username<input class="name-input" id="onName" readonly value="'+escapeHTML(accountName)+'"></label><p class="onboard-subtitle">Your Hafrik username is your name in the game.</p>':'<label>Your name<input class="name-input" id="onName" maxlength="22" placeholder="Your name" value="'+escapeHTML(onboard.name)+'"></label><p class="onboard-subtitle">Connect Hafrik later to save across devices — your Hafrik username then becomes your name.</p>')+
   '<h3>Skin tone</h3>'+pick('skin',[['#603c2c','Deep brown',1],['#8b5c43','Warm brown',1],['#b9825d','Golden brown',1],['#e1b596','Light warm',1]],onboard.skin||'#8b5c43')+
   '<h3>Hairstyle</h3>'+pick('hair',[['cropped','Cropped'],['bun','Bun'],['cap','Cap']],onboard.hair||'cropped')+
   '<h3>Outfit</h3>'+pick('color',[['#ef9f79','Warm sunset',1],['#4e8c9a','Winter blue',1],['#bc8bc2','City violet',1],['#6c9b72','Pine green',1]],onboard.color)+
   '<p class="fine-print">You can change your look any time from your profile.</p>';
 }
 $('onboardContent').innerHTML=h;
 if(s===0)$('onboardContent').querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{onboard.start=b.dataset.start;onboarding()});
 if(s===1)$('onboardContent').querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{onboard.role=b.dataset.role;onboarding()});
 if(s===2){if(!accountName)$('onName').oninput=e=>onboard.name=e.target.value;for(const key of ['skin','hair','color'])$('onboardContent').querySelectorAll('[data-'+key+']').forEach(b=>b.onclick=()=>{onboard[key]=b.dataset[key];onboarding()})}
}
function studentProfile(start){const school=window.ChinaLifeStudentStory.universities[0];return {start,path:'study',country:start==='outside'?'Nigeria':'China',departure:start==='outside'?'Lagos':'Shenyang',studyCity:'Shenyang',university:school[1],studyLevel:'Undergraduate',major:'',campus:school[0],temporary:false}}
function next(){
 if(step===0&&!onboard.start)return toast('Choose where your ChinaLife begins.');
 if(accountName)onboard.name=accountName;
 const attaching=studentSetupMode==='attach';
 if(attaching){
  // An older Student character opting into the student story: keep all progress.
  state=JSON.parse(JSON.stringify(state));state.student=studentProfile(onboard.start);state.story={version:1,phase:'arrival',index:onboard.start==='outside'?0:1,season:'winter'};state.logs.unshift('Your student story begins.');studentSetupMode='create';save();$('onboarding').close();render();studentStory();return;
 }
 if(step===1&&!roles[onboard.role])return toast('Choose your role.');
 if(step===2&&!accountName&&(!onboard.name.trim()||onboard.name.trim().length>22))return toast('Choose a name with 1–22 characters.');
 if(step<2){step++;onboarding();return}
 const role=roles[onboard.role];
 state={...JSON.parse(JSON.stringify(blank)),created:true,name:onboard.name.trim(),color:onboard.color,appearance:{skin:onboard.skin||'#8b5c43',hair:onboard.hair||'cropped',trousers:'#28394b'},background:onboard.role,money:role.money};
 state.skills[role.skill]=2;state.city='Shenyang';
 if(onboard.role==='Student'){state.student=studentProfile(onboard.start);state.story={version:1,phase:'arrival',index:onboard.start==='outside'?0:1,season:'winter'};state.place=onboard.start==='outside'?'airport':state.student.campus}
 else state.place=onboard.start==='outside'?'airport':role.home;
 selected=state.place;state.visited=[state.place];state.logs=[onboard.start==='outside'?'You landed in Shenyang as a '+role.label.toLowerCase()+'.':'Your '+role.label.toLowerCase()+' life in Shenyang begins.'];
 studentSetupMode='create';save();$('onboarding').close();render();toast('Welcome to ChinaLife, '+state.name+'! Open your phone to see your goals.');
}

function studentStory(){
 if(!state.student){screen('Your student story','Season 0 · Student Life', '<p>Add your student profile and begin the Shenyang introduction. Your money, skills, friendships and existing progress are kept.</p>'+(state.background==='Student'?action('startStudentIntro','Add your student profile','Choose where you start and get your campus tasks'):'<p>Your '+escapeHTML(state.background)+' story is coming soon.</p>'));if($('startStudentIntro'))$('startStudentIntro').onclick=()=>{$('activityDialog').close();studentSetupMode='attach';step=0;onboard={name:state.name,color:state.color,start:'inside'};$('onboarding').showModal();onboarding()};return}
 const storyState=state,p=state.student,s=state.story,school=escapeHTML(p.university),temporary=p.temporary;
 const profile='<div class="student-profile"><b>'+school+'</b><span>'+escapeHTML(p.studyCity)+' · Student</span>'+(temporary?'<p>Your requested city or university is coming soon. Play at the temporary Shenyang campus while keeping your actual university in your profile.</p>':'')+'</div>';
 const login=!window.ChinaLifeCloud?.signedIn?'<button id="storySaveAccount" class="soft-btn">Save with Hafrik across devices</button>':'';
 if(s.phase==='complete'){screen('Your arrival introduction is complete','Your student life continues.',profile+'<p>Your room is ready, you have attended your first class and met the student community. Explore classes, clubs, food and friendships at your own pace.</p>'+action('storyCampus','Go to your playable campus',temporary?'Temporary Shenyang campus':p.university)+login);$('storyCampus').onclick=()=>{$('activityDialog').close();select(p.campus)};if($('storySaveAccount'))$('storySaveAccount').onclick=()=>{$('activityDialog').close();window.ChinaLifeCloud?.open()};return}
 const steps=window.ChinaLifeStudentStory.arrival,chapter=steps[s.index],venue=chapter.place==='campus'?p.campus:chapter.place,here=state.city==='Shenyang'&&state.place===venue;
 screen(chapter.title,'Student tasks · Shenyang · Winter',profile+'<p class="story-progress">Task '+(s.index+1)+' of '+steps.length+'</p><progress max="'+steps.length+'" value="'+s.index+'"></progress><p>'+escapeHTML(chapter.text)+'</p>'+action('storyNext',here?chapter.button:'Travel to '+(L.find(v=>v[0]===venue)?.[1]||'your venue'),here?'Continue your student story':'Complete this task at its venue')+login);
 $('storyNext').onclick=()=>{
  if(state!==storyState||state.story.phase!==s.phase||state.story.index!==s.index)return;
  if(!here){$('activityDialog').close();if(state.city!=='Shenyang'){toast('Return to Shenyang to continue your first-week story.');tripScreen();return}select(venue);return}
  if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:chapter.hunger?'eat':chapter.study?'study':'talk',x:0,z:2,label:chapter.title},$('storyNext').onclick);
  if(chapter.hunger)state.needs.hunger=Math.min(100,state.needs.hunger+chapter.hunger);if(chapter.social)state.needs.social=Math.min(100,state.needs.social+chapter.social);if(chapter.study)gain('Study',chapter.study);advance(chapter.minutes||30);state.xp+=10;state.logs.unshift(chapter.title+' completed.');
  // Replace the chapter object so a delayed duplicate callback cannot advance twice.
  const index=s.index+1;state.story=index<steps.length?{...s,index}:{version:1,phase:'complete',index:0,season:'winter'};
  save();render();studentStory();
 };
 if($('storySaveAccount'))$('storySaveAccount').onclick=()=>{$('activityDialog').close();window.ChinaLifeCloud?.open()};
}

function appearanceScreen(){const a=state.appearance;const skins=[['#603c2c','Deep brown'],['#8b5c43','Warm brown'],['#b9825d','Golden brown'],['#e1b596','Light warm']];const outfits=[['#18776d','Teal'],['#426dba','Blue'],['#b35777','Rose'],['#c59642','Gold']];screen('Your character','Your appearance changes immediately in the city.','<h3>Skin tone</h3><div class="look-grid">'+skins.map((v,i)=>action('skin'+i,v[1]+(a.skin===v[0]?' ✓':''),'Choose skin tone')).join('')+'</div><h3>Hairstyle</h3><div class="look-grid">'+['cropped','bun','cap'].map(v=>action('hair-'+v,v[0].toUpperCase()+v.slice(1)+(a.hair===v?' ✓':''),'Choose hairstyle')).join('')+'</div><h3>Outfit</h3><div class="look-grid">'+outfits.map((v,i)=>action('outfit'+i,v[1]+(state.color===v[0]?' ✓':''),'Choose top colour')).join('')+'</div>');skins.forEach((v,i)=>$('skin'+i).onclick=()=>{a.skin=v[0];save();render();appearanceScreen()});['cropped','bun','cap'].forEach(v=>$('hair-'+v).onclick=()=>{a.hair=v;save();render();appearanceScreen()});outfits.forEach((v,i)=>$('outfit'+i).onclick=()=>{state.color=v[0];save();render();appearanceScreen()})}
function validateSave(v){const bad=(field='character data')=>{throw new Error('Your saved character could not be loaded ('+field+'). Your account save has not been replaced.')};if(!v||v.created!==true)bad('character status');if(typeof v.name!=='string'||!v.name.trim()||v.name.length>64)bad('character name');if(!['Student','Worker','Creator','Entrepreneur','Tourist'].includes(v.background))bad('background');if(!L.some(p=>p[0]===v.place))bad('current venue');const num=(value,min,max,field='numeric progress')=>{if(typeof value==='string'&&/^-?\d+(\.\d+)?$/.test(value))value=Number(value);if(!Number.isFinite(value))bad(field);return Math.min(max,Math.max(min,value))};const list=(value,allowed)=>Array.isArray(value)?[...new Set(value.filter(x=>allowed.includes(x)))].slice(0,100):[];const r=JSON.parse(JSON.stringify(blank));r.created=true;r.name=v.name.trim();r.background=v.background;r.place=v.place;r.city=v.city??'Shenyang';if(!Object.keys(cityData).includes(r.city))bad('current city');r.day=num(v.day,1,36500,'day');r.hour=num(v.hour,0,1439,'hour');r.day=Math.round(r.day);r.hour=Math.round(r.hour);r.money=num(v.money,-10000000,1000000000,'money');r.transferTotal=num(v.transferTotal??0,-1000000000,1000000000);r.xp=num(v.xp,0,10000000,'xp');r.color=/^#[0-9a-f]{6}$/i.test(v.color)?v.color:'#18776d';v={...v,needs:v.needs||{},skills:v.skills||{}};for(const k of needs)r.needs[k]=num(v.needs[k]??60,0,100,k+' need');r.skills={};r.skillXP={};for(const k of ['Chinese','Social','Digital','Creativity','Fitness','Study','Network']){r.skills[k]=num(v.skills[k]??1,1,99);r.skillXP[k]=num(v.skillXP?.[k]??0,0,99)}r.trait=list(v.trait||[],traits,'personality traits');r.dream=['','0','1','2','3'].includes(v.dream)?v.dream:'';r.visited=list(v.visited,L.map(p=>p[0]),'visited venues');r.upgrades=list(v.upgrades||[],catalog.furniture.map(f=>f.id),'furniture inventory');r.properties={};for(const [city,type] of Object.entries(v.properties||{})){if(!Object.keys(cityData).includes(city)||!catalog.properties.some(p=>p.id===type))continue;r.properties[city]=type}r.furnitureColors={};for(const [id,color] of Object.entries(v.furnitureColors||{})){if(!catalog.furniture.some(f=>f.id===id)||!/^#[0-9a-f]{6}$/i.test(color))continue;r.furnitureColors[id]=color}r.flightBookings=(Array.isArray(v.flightBookings)?v.flightBookings:[]).filter(f=>!(!f||typeof f.id!=='string'||!/^[a-z0-9-]{1,40}$/.test(f.id)||!Object.keys(cityData).includes(f.from)||!Object.keys(cityData).includes(f.to)||f.from===f.to||!['booked','flown','cancelled'].includes(f.status))).slice(-20).map(f=>{try{return {id:f.id,from:f.from,to:f.to,status:f.status,fare:num(f.fare,1,10000),hours:num(f.hours,1,12),day:num(f.day,1,36500)}}catch{return null}}).filter(Boolean);r.trips=list(v.trips||[],['Harbin','Beijing','Shanghai','Guangzhou','Shenzhen','Chengdu']);r.claimed=list(v.claimed||[],['explorer','routine','payday','language','friend','home','founder']);r.logs=Array.isArray(v.logs)?v.logs.filter(x=>typeof x==='string').slice(0,40).map(x=>x.slice(0,500)):[];r.job=['cafe-job','teacher','content','designer','sales','coach'].includes(v.job)?v.job:null;r.jobStart=num(v.jobStart??1,1,36500);r.lastShift=num(v.lastShift??0,0,36500);r.shifts=num(v.shifts??0,0,100000);r.promotion=num(v.promotion??1,1,5);r.stats={activities:num(v.stats?.activities??0,0,1000000),shifts:num(v.stats?.shifts??r.shifts,0,1000000),businessOrders:num(v.stats?.businessOrders??0,0,1000000)};r.friends={};r.friendDay={};for(const id of ['mei','tunde','amina','leo']){r.friends[id]=num(v.friends?.[id]??0,0,100);r.friendDay[id]=num(v.friendDay?.[id]??0,0,36500)}r.eventHistory={};for(const k of Object.keys(v.eventHistory||{})){if(!/^[0-9]+$/.test(k)||+k<1||+k>36500||![0,1].includes(v.eventHistory[k]))continue;r.eventHistory[k]=v.eventHistory[k]}r.business=v.business?{level:num(v.business.level,1,3),orders:num(v.business.orders,0,100000),revenue:num(v.business.revenue,0,1000000000),lastOrder:num(v.business.lastOrder,0,36500)}:null;r.paidActivities={};for(const key of ['cafe:1'])r.paidActivities[key]=num(v.paidActivities?.[key]??0,0,36500);r.pantryDay=num(v.pantryDay??0,0,36500);r.dreamClaimed=v.dreamClaimed===true;r.reduceMotion=v.reduceMotion===true;if(v.student){const p=v.student;if(!['inside','outside'].includes(p.start)||!['campus','university','liaoning','dongbei'].includes(p.campus))bad('student origin or campus');for(const key of ['country','departure','studyCity','university'])if(typeof p[key]!=='string'||!p[key].trim()||p[key].length>100)bad('student '+key);if(!window.ChinaLifeStudentStory.studyLevels.includes(p.studyLevel||'Undergraduate')||typeof (p.major??'')!=='string'||(p.major||'').length>100)bad('study level or major');r.student={start:p.start,path:'study',studyLevel:p.studyLevel||'Undergraduate',major:p.major||'',country:p.country,departure:p.departure,studyCity:p.studyCity,university:p.university,campus:p.campus,temporary:p.temporary===true};const story=v.story;if(!story||!['preparation','arrival','complete'].includes(story.phase)||(story.version!==undefined&&story.version!==1)||!Number.isInteger(story.index)||story.index<0||story.index>=(story.phase==='preparation'?window.ChinaLifeStudentStory.preparation.length:story.phase==='arrival'?window.ChinaLifeStudentStory.arrival.length:1))bad('student story progress');r.story=story.phase==='preparation'?{version:1,phase:'arrival',index:0,season:'winter'}:{version:1,phase:story.phase,index:story.index,season:'winter'}}r.appearance={skin:/^#[0-9a-f]{6}$/i.test(v.appearance?.skin)?v.appearance.skin:'#8b5c43',hair:['cropped','bun','cap'].includes(v.appearance?.hair)?v.appearance.hair:'cropped',trousers:'#28394b'};return r}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function ensure(){if(!isOpen(state.city)){state.city='Shenyang';state.place='home';selected='home'}state.properties=state.properties||{};state.furnitureColors=state.furnitureColors||{};state.flightBookings=state.flightBookings||[];state.city=state.city||'Shenyang';applyCity();state.paidActivities=state.paidActivities||{};state.appearance=state.appearance||{skin:'#8b5c43',hair:'cropped',trousers:'#28394b'};state.claimed=state.claimed||[];state.eventHistory=state.eventHistory||{};state.stats=state.stats||{activities:0,shifts:state.shifts||0,businessOrders:0};state.business=state.business||null;state.skillXP=state.skillXP||{};state.friends=state.friends||{};state.upgrades=state.upgrades||[];state.trips=state.trips||[];state.skills.Study=state.skills.Study||1;state.skills.Network=state.skills.Network||1;state.promotion=state.promotion||1;state.shifts=state.shifts||0}
function gain(skill,amount){ensure();state.skills[skill]=state.skills[skill]||1;state.skillXP[skill]=(state.skillXP[skill]||0)+amount;while(state.skillXP[skill]>=100){state.skillXP[skill]-=100;state.skills[skill]++;toast(skill+' reached level '+state.skills[skill])}}
let runningCallback=false;function sceneAction(spec,fn){return window.ChinaLifeWorld.perform({...spec,place:state.place},()=>{runningCallback=true;try{fn()}finally{runningCallback=false}})}
function screen(title,intro,body){$('activityDialog').classList.remove('travel-sheet');$('activityContent').innerHTML='<div class="activity-panel"><span class="eyebrow">YOUR LIFE IN CHINA</span><h2>'+title+'</h2><p class="lead">'+intro+'</p>'+body+'</div>';if(!$('activityDialog').open)$('activityDialog').showModal()}
function action(id,title,sub){return '<button class="choice-action" id="'+id+'"><b>'+title+'</b><span>'+sub+'</span></button>'}
function finish(msg){state.logs.unshift(msg);state.logs=state.logs.slice(0,40);save();render();toast(msg)}
function workShift(style){const j=jobs.find(x=>x[0]===state.job);if(!j)return jobsDialog();const workplace=L.find(p=>p[1]===j[2]);if(state.place!==workplace[0])return toast('Travel to '+j[2]+' for your shift.');if(state.day<(state.jobStart||1))return toast('Your job starts tomorrow. Rest or train today.');if(state.lastShift===state.day)return toast('You have already worked today.');if(state.needs.energy<35||state.needs.hunger<25)return toast('Eat and rest before your shift.');if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:state.place==='cafe'?'serve':state.place==='gym'?'exercise':'type',x:0,z:state.place==='cafe'?-1.8:0,label:'Working your shift'},()=>workShift(style));const pay=Math.round(j[4]*(1+(state.promotion-1)*.15)*(style==='focus'?1.15:1));state.lastShift=state.day;state.money+=pay;state.shifts++;state.stats.shifts++;state.needs.energy=Math.max(0,state.needs.energy-(style==='focus'?38:26));state.needs.hunger=Math.max(0,state.needs.hunger-20);advance(j[5]*60);gain(j[3],style==='focus'?35:25);state.xp+=25;if(state.shifts%3===0&&state.promotion<5)state.promotion++;$('activityDialog').close();finish('Shift complete: earned ¥'+pay+'. Career level '+state.promotion+'/5.')}
function shiftScreen(){const j=jobs.find(x=>x[0]===state.job);if(!j)return jobsDialog();const workplace=L.find(p=>p[1]===j[2]);if(state.place!==workplace[0]){screen(j[1],'Your shift takes place at '+j[2]+'.',action('goWork','Travel to work',j[2]));$('goWork').onclick=()=>{$('activityDialog').close();select(workplace[0])};return}screen(j[1],'Career level '+state.promotion+'/5 · '+state.shifts+' shifts completed. One shift per game day.',action('steadyShift','Steady shift','Balanced pace · '+j[5]+' hours')+action('focusShift','Focused shift','15% extra pay · uses more energy'));$('steadyShift').onclick=()=>workShift('steady');$('focusShift').onclick=()=>workShift('focus')}
function skillsScreen(){screen('Your skills','Every five training activities raises a skill level. Higher skills unlock new careers.',Object.keys(state.skills).map(k=>'<div class="skill-item"><b>'+k+' · Level '+state.skills[k]+'</b><progress max="100" value="'+(state.skillXP[k]||0)+'"></progress><span>'+(state.skillXP[k]||0)+'/100 to next level</span></div>').join(''))}
const contacts=[['mei','Mei','campus','Student · enjoys language exchanges'],['tunde','Tunde','business','Founder · building a small studio'],['amina','Amina','ef','New arrival · looking for a study partner'],['leo','Leo','gym','Trainer · always ready for basketball']];
function peopleScreen(){screen('People in your city','Four simulated characters, each with a story. Visit their usual spot to talk.',contacts.map(c=>action('friend-'+c[0],c[1]+' · '+((state.friends[c[0]]||0)>=60?'Close friend':(state.friends[c[0]]||0)>=30?'Friend':'Acquaintance'),c[3]+' · Bond '+(state.friends[c[0]]||0)+'/100')).join(''));contacts.forEach(c=>$('friend-'+c[0]).onclick=()=>personScreen(c[0]))}
const dialogue={mei:{intro:'I came here to study engineering. At first, I was too nervous to speak in class. Language exchanges helped.',skill:'Chinese',answers:['Let’s practise a phrase together. Getting it wrong is part of learning.','The EFH language class is a good place to start. A little practice each day adds up.','I miss home too sometimes. Sharing the small wins makes this city feel less lonely.']},tunde:{intro:'I’m building a creative studio. Finding my first client was harder than setting up the business.',skill:'Network',answers:['Tell me what you are working on. There might be someone I can introduce you to.','Train your Digital and Network skills before opening a studio. Start small and deliver consistently.','That reminds me of my first week here. Nothing went to plan, but I met people who helped.']},amina:{intro:'I’ve just arrived. I’m still figuring out the buses, the food, and where to find people to study with.',skill:'Study',answers:['Want to study together sometime? It helps to have someone to compare notes with.','Try a campus lecture and join the international club. That is how I started finding my way.','Thank you for sharing that. It makes starting over feel a little less frightening.']},leo:{intro:'Training keeps me grounded. You don’t have to be good at basketball to join us.',skill:'Fitness',answers:['Come back for a workout. Consistency matters more than a perfect first session.','Keep your energy and hunger balanced before training. A walk in Nanhu Park also helps.','We all have those days. The next game is a fresh start.']}};
function talkNPC(id,topic){const c=contacts.find(c=>c[0]===id);if(!c||!Number.isInteger(topic)||topic<0||topic>2)return false;if(state.place!==c[2])return false;if(state.friendDay?.[id]===state.day){toast('Catch up with '+c[1]+' again tomorrow.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:'talk',x:-2+contacts.filter(p=>p[2]===c[2]).findIndex(p=>p[0]===id)*2,z:2.1,label:'Catch up with '+c[1]},()=>talkNPC(id,topic));return false}state.friendDay=state.friendDay||{};state.friendDay[id]=state.day;state.friends[id]=Math.min(100,(state.friends[id]||0)+15);state.needs.social=Math.min(100,state.needs.social+20);state.needs.fun=Math.min(100,state.needs.fun+5);gain(topic===1?dialogue[id].skill:'Social',20);advance(45);finish(c[1]+': '+dialogue[id].answers[topic]);return true}
function personScreen(id){const c=contacts.find(c=>c[0]===id);if(!c){const p=L.find(p=>p[0]===state.place);screen('Welcome to '+p[1],'Venue host · simulated character','<p>Make yourself comfortable. You can find today’s activities below.</p>'+p[7].map((a,i)=>action('hostAct'+i,a[0],a[1])).join(''));p[7].forEach((a,i)=>$('hostAct'+i).onclick=()=>activity(p,i));return}const d=dialogue[id],here=state.place===c[2],done=state.friendDay?.[id]===state.day;screen(c[1],c[3]+' · Bond '+(state.friends[id]||0)+'/100','<blockquote class="npc-quote">'+d.intro+'</blockquote>'+(state.friends[id]>=60?'<p>You are close friends. '+c[1]+' is glad to see you.</p>':'')+(here?['Ask about their day','Ask for local advice','Share a story from home'].map((t,i)=>action('topic'+i,done?'Talked today':t,'45 minutes · friendship and skill growth')).join(''):action('meetTravel','Go and meet '+c[1],L.find(p=>p[0]===c[2])[1])));if(here)[0,1,2].forEach(i=>{$('topic'+i).disabled=done;$('topic'+i).onclick=()=>{if(talkNPC(id,i))screen(c[1],'Bond '+state.friends[id]+'/100 · conversation complete','<blockquote class="npc-quote">'+d.answers[i]+'</blockquote>'+action('backPeople','Back to people','Catch up again tomorrow'));if($('backPeople'))$('backPeople').onclick=peopleScreen}});else $('meetTravel').onclick=()=>{$('activityDialog').close();select(c[2])}}

function travelScreen(id){const target=L.find(p=>p[0]===id);screen('Go to '+target[1],'Choose your ride. Game fares use virtual yuan.',action('walkTravel','Walk · free','45 minutes · uses 8 energy')+action('metroTravel','Metro · ¥4','20 minutes · uses 2 energy')+action('cabTravel','Taxi · ¥25','10 minutes · no energy cost'));$('activityDialog').classList.add('travel-sheet');[['walkTravel',0,45,8],['metroTravel',4,20,2],['cabTravel',25,10,0]].forEach(t=>$(t[0]).onclick=()=>{if(t[1]>0&&state.money<t[1])return toast('You need more virtual yuan.');const slowHome=id==='home'&&t[1]===0&&state.needs.energy<t[3];if(state.needs.energy<t[3]&&!slowHome)return toast('Choose transport or rest first.');if(!runningCallback&&window.ChinaLifeWorld){const commit=$(t[0]).onclick;const mode=t[0]==='walkTravel'?'walk':t[0]==='cabTravel'?'cab':'metro';return window.ChinaLifeWorld.journey({from:state.place,to:id,mode,label:'To '+target[1]},()=>{runningCallback=true;try{commit()}finally{runningCallback=false}})}state.money-=t[1];state.needs.energy=Math.max(0,state.needs.energy-t[3]);advance(slowHome?90:t[2]);$('activityDialog').close();arrive(id);finish('Arrived at '+target[1]+'.')})}
function tripScreen(){const cities=Object.entries(cityData);screen('Choose your city','Travel changes your playable map. Fares and journey times are fictional game values. Your furnished apartment is available in every city.',action('openFlights','Book a flight','Visit the airport and choose your destination')+'<div class="city-picker">'+cities.map(([name,c],i)=>action('trip-'+i,c.han+' · '+name+(state.city===name?' · Here':isOpen(name)?'':' · Coming soon'),isOpen(name)?c.tag+' · '+(state.city===name?'Explore this city':'¥'+c.fare+' · '+c.hours+'h'):'We are building '+name+'. Shenyang is open now.')).join('')+'</div><p class="map-note">These are game maps. Unnamed businesses, restaurants and churches are fictional venues.</p>');$('openFlights').onclick=airportScreen;cities.forEach(([name,c],i)=>$('trip-'+i).onclick=()=>{if(!isOpen(name))return toast(name+' is coming soon. Keep exploring Shenyang.');if(state.city===name){$('activityDialog').close();window.ChinaLifeWorld?.map();return}if(state.money<c.fare)return toast('Save more virtual yuan before travelling.');state.money-=c.fare;advance(c.hours*60);state.city=name;state.place='station';selected='station';applyCity();state.needs.fun=Math.min(100,state.needs.fun+20);if(name!=='Shenyang'&&!state.trips.includes(name)){state.trips.push(name);state.xp+=60}if(!state.visited.includes('station'))state.visited.push('station');$('activityDialog').close();finish('You arrived in '+name+'. Explore your new city.');window.ChinaLifeWorld?.map()})}
function hafrikScreen(){screen('Hafrik','Your community beyond the game.','<a class="primary-btn external-app" href="https://hafrik.com" target="_blank" rel="noopener noreferrer">Open Hafrik</a><p>Connect with foreigners in China, join Spaces and find community events. Your Hafrik account is separate from this prototype.</p>')}
function whatsappScreen(){screen('WhatsApp','Continue a conversation in your own WhatsApp app.','<p>Enter a number shared with you voluntarily, including its country code. ChinaLife does not read your contacts or WhatsApp messages.</p><form id="whatsappForm"><label for="whatsappNumber">Phone number</label><input id="whatsappNumber" type="tel" class="name-input" placeholder="+86 or +234…" autocomplete="off" maxlength="20"><button class="primary-btn" type="submit">Open WhatsApp chat</button></form><p>For conversations inside ChinaLife, use the Chat app.</p>'+action('openGameChat','Open ChinaLife Chat','Venue chat, friends and private conversations'));$('openGameChat').onclick=()=>window.ChinaLifeSocial?.open();$('whatsappForm').onsubmit=e=>{e.preventDefault();const number=$('whatsappNumber').value.replace(/[\s()+-]/g,'');if(!/^[1-9]\d{7,14}$/.test(number))return toast('Enter a valid number with its country code.');window.open('https://wa.me/'+number,'_blank','noopener,noreferrer')}}

function rentDue(){return state.properties?.[state.city]?0:(state.background==='Student'?600:state.background==='Creator'?1200:2400)}
const furniture=[['bed','Comfortable bed',450,'Rest restores 15 extra energy'],['kitchen','Kitchen kit',280,'Home meals restore 10 extra hunger'],['desk','Study desk',650,'Train Digital at home']];
function homeScreen(){if(state.place!=='home'){screen('Your apartment','Return home to rest, cook or manage your furniture.',action('goHome','Travel home','Choose how to get back'));$('goHome').onclick=()=>{$('activityDialog').close();select('home')};return}screen('Make yourself at home',''+(state.properties[state.city]?'Owned '+state.properties[state.city]+' · ':'Rented home · ')+'Weekly rent: ¥'+(rentDue())+'. Next due on day '+(state.day+(7-state.day%7))+'.',action('homeShop','Furniture & property shop','See the products, choose a finish and buy with virtual yuan')+action('homeRest','Sleep until morning','Move to 08:00 tomorrow · restore energy')+action('homeShower','Shower and freshen up','30 minutes · restore hygiene and bladder')+(state.money<18&&state.pantryDay!==state.day?action('pantryMeal','Use your emergency pantry','Free basic meal · once per day · restores hunger'):'')+furniture.map(f=>action('buy-'+f[0],f[1]+(state.upgrades.includes(f[0])?' · Owned':' · ¥'+f[2]),f[3])).join('')+(state.upgrades.includes('desk')?action('homeStudy','Work at your desk','2 hours · trains Digital · uses 12 energy'):''));$('homeShop').onclick=shopScreen;if($('pantryMeal'))$('pantryMeal').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'eat',x:1,z:3.2,label:'Have a pantry meal'},$('pantryMeal').onclick);if(state.pantryDay===state.day)return;state.pantryDay=state.day;state.needs.hunger=Math.min(100,state.needs.hunger+35);advance(30);finish('A basic pantry meal helped you get back on your feet.');homeScreen()};$('homeRest').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'sleep',x:-3,z:1,label:'Sleep until morning'},$('homeRest').onclick);advance(1440-state.hour+480);state.needs.energy=state.upgrades.includes('bed')?100:85;state.needs.hunger=Math.max(0,state.needs.hunger-10);arrive('home');finish('A new morning. Your next move is yours.');homeScreen()};$('homeShower').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'wash',x:4,z:3,label:'Freshen up'},$('homeShower').onclick);advance(30);state.needs.hygiene=100;state.needs.bladder=100;arrive('home');finish('Freshened up and ready.');homeScreen()};furniture.forEach(f=>$('buy-'+f[0]).onclick=()=>{if(state.upgrades.includes(f[0]))return toast('You already own this.');if(state.money<f[2])return toast('You need more virtual yuan.');state.money-=f[2];state.upgrades.push(f[0]);finish('Your home now has a '+f[1].toLowerCase()+'.');homeScreen()});if($('homeStudy'))$('homeStudy').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'type',x:3,z:-0.8,label:'Work at your desk'},$('homeStudy').onclick);if(state.needs.energy<12)return toast('Rest first.');state.needs.energy-=12;advance(120);gain('Digital',25);finish('Two focused hours at your new desk.');homeScreen()}}
let shopMode='furniture',shopItem='bed',shopColor='#16897b';
function shopScreen(mode=shopMode,id=shopItem){shopMode=mode;const items=mode==='properties'?catalog.properties:catalog.furniture;shopItem=items.some(f=>f.id===id)?id:items[0].id;const item=items.find(f=>f.id===shopItem),owned=mode==='properties'?state.properties[state.city]===item.id:state.upgrades.includes(item.id);shopColor=state.furnitureColors[item.id]||shopColor;screen('Make room for your life','Virtual furniture and personal game homes. Purchases are saved with your character.','<div class="shop-tabs"><button id="shopFurniture" class="'+(mode==='furniture'?'active':'')+'">Furniture</button><button id="shopProperties" class="'+(mode==='properties'?'active':'')+'">Homes in '+state.city+'</button></div><div class="shop-preview"><div id="productPreview" aria-label="Three-dimensional product preview"></div><button id="rotateProduct">Rotate preview ↻</button></div><div class="shop-product"><div><h3>'+item.name+'</h3><p>'+item.detail+'</p></div><strong>¥'+item.price.toLocaleString()+'</strong></div>'+(mode==='furniture'?'<div class="finish-picker">'+[['#16897b','Teal'],['#426dba','Blue'],['#d6a362','Sand']].map(([c,name])=>'<button data-finish="'+c+'" class="'+(shopColor===c?'active':'')+'">'+name+'</button>').join('')+'</div>':'')+'<button id="shopBuy" class="primary-btn shop-buy">'+(owned?(mode==='furniture'?'Apply this finish':'You own this home'):'Buy '+item.name+' · ¥'+item.price.toLocaleString())+'</button><div class="shop-grid">'+items.map(f=>'<button class="shop-card '+(f.id===item.id?'selected':'')+'" data-item="'+f.id+'"><canvas data-product="'+f.id+'" width="240" height="160" aria-label="'+f.name+' preview"></canvas><b>'+f.name+'</b><span>¥'+f.price.toLocaleString()+(mode==='furniture'&&state.upgrades.includes(f.id)?' · Owned':'')+'</span></button>').join('')+'</div><p class="map-note">Furniture is installed in fixed room positions. Home ownership removes rent in this city. Changing your home type costs the full purchase price.</p>');$('shopFurniture').onclick=()=>shopScreen('furniture','bed');$('shopProperties').onclick=()=>shopScreen('properties','apartment');$('activityContent').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>shopScreen(mode,b.dataset.item));$('activityContent').querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>{shopColor=b.dataset.finish;previewShop();b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b))});$('rotateProduct').onclick=()=>window.ChinaLifePreview?.rotate();$('shopBuy').disabled=mode==='properties'&&owned;$('shopBuy').onclick=()=>{if(mode==='furniture'){if(!state.upgrades.includes(item.id)){if(state.money<item.price)return toast('You need more virtual yuan.');state.money-=item.price;state.upgrades.push(item.id)}state.furnitureColors[item.id]=shopColor;finish(item.name+' is ready in your home.')}else{if(state.properties[state.city]===item.id)return;if(state.money<item.price)return toast('You need more virtual yuan.');state.money-=item.price;state.properties[state.city]=item.id;finish('You now own a '+item.name.toLowerCase()+' in '+state.city+'.')}shopScreen(mode,item.id)};previewShop()}
function previewShop(){window.dispatchEvent(new CustomEvent('chinalife:preview',{detail:{mode:shopMode,id:shopItem,color:shopColor}}))}
function flightQuote(from,to){const grid={Shenyang:[6,1],Harbin:[6,0],Beijing:[4,2],Shanghai:[6,4],Guangzhou:[3,6],Shenzhen:[4,6],Chengdu:[1,4]},a=grid[from],b=grid[to],distance=Math.hypot(a[0]-b[0],a[1]-b[1]);return {fare:Math.round((200+distance*140)/10)*10,hours:Math.max(2,Math.ceil(distance*.7))}}
function airportScreen(){if(state.place!=='airport'){screen('Flights from '+state.city,'Visit the airport to book, board or cancel a game flight.',action('goAirport','Travel to the airport',state.city+' Airport'));$('goAirport').onclick=()=>{$('activityDialog').close();select('airport')};return}const destinations=Object.entries(cityData).filter(([city])=>city!==state.city);screen(state.city+' Airport','Choose a destination. Booking charges virtual yuan; boarding completes the journey. These are game flights, not real airline bookings.','<h3>Your tickets</h3>'+state.flightBookings.filter(f=>f.status==='booked').map(f=>'<div class="boarding-pass"><b>'+f.from+' ✈ '+f.to+'</b><span>CL-'+f.id.toUpperCase()+' · ¥'+f.fare+' · '+f.hours+'h</span><button data-board="'+f.id+'">Board flight</button><button data-cancel="'+f.id+'">Cancel · 90% refund</button></div>').join('')+'<h3>Departures from '+state.city+'</h3>'+destinations.map(([city,c],i)=>action('flight-'+i,city+(isOpen(city)?' · Economy':' · Coming soon'),isOpen(city)?'¥'+flightQuote(state.city,city).fare+' · '+flightQuote(state.city,city).hours+' hours in game':'Flights open when '+city+' launches')).join(''));destinations.forEach(([city,c],i)=>$('flight-'+i).onclick=()=>{if(!isOpen(city))return toast(city+' is coming soon.');const fare=flightQuote(state.city,city).fare;if(state.money<fare)return toast('You need more virtual yuan.');if(state.flightBookings.filter(f=>f.status==='booked').length>=3)return toast('You can hold three active tickets. Board or cancel one first.');state.money-=fare;state.flightBookings.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),from:state.city,to:city,fare,hours:flightQuote(state.city,city).hours,day:state.day,status:'booked'});if(state.flightBookings.length>20)state.flightBookings=state.flightBookings.slice(-20);finish('Ticket booked: '+state.city+' to '+city+'.');airportScreen()});$('activityContent').querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.board);if(!f||f.status!=='booked')return;if(f.from!==state.city)return toast('This flight departs from '+f.from+'.');if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'phone',x:2,z:-1.7,label:'Boarding for '+f.to},b.onclick);f.status='flown';advance(f.hours*60);state.city=f.to;state.place='airport';selected='airport';applyCity();if(f.to!=='Shenyang'&&!state.trips.includes(f.to)){state.trips.push(f.to);state.xp+=60}if(!state.visited.includes('airport'))state.visited.push('airport');$('activityDialog').close();finish('Landed in '+f.to+'. Welcome to your next chapter.');window.ChinaLifeWorld?.venue('airport')});$('activityContent').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.cancel);if(!f||f.status!=='booked')return;f.status='cancelled';state.money+=Math.floor(f.fare*.9);finish('Flight cancelled. 90% of the virtual fare was refunded.');airportScreen()})}
function profileScreen(){screen(escapeHTML(state.name||'New arrival'),'Level '+level()+' · '+roleOf().label+' · '+state.visited.length+' places explored', action('profileStory','Your student story','Your starting point, university and current chapter')+action('profileLook','Edit your appearance','Choose skin tone, hairstyle and outfit')+'<p><b>Your dream:</b> '+(dreams[+state.dream]?.[0]||'Find your direction')+'</p><p>'+state.trips.length+' cities visited · '+Object.values(state.friends).filter(v=>v>=60).length+' close friends · '+state.upgrades.length+' home upgrades</p><h3>Your journal</h3>'+state.logs.slice(0,10).map(l=>'<p class="journal-item">'+escapeHTML(l)+'</p>').join(''));$('profileLook').onclick=appearanceScreen;$('profileStory').onclick=studentStory}

const quests=[
{id:'explorer',title:'Find your feet',detail:'Visit five city venues',target:5,value:()=>state.visited.length,money:120,xp:30},
{id:'routine',title:'Build a routine',detail:'Complete ten location activities',target:10,value:()=>state.stats.activities,money:180,xp:50},
{id:'payday',title:'Earn your place',detail:'Finish three career shifts',target:3,value:()=>state.stats.shifts,money:250,xp:60},
{id:'language',title:'Speak with confidence',detail:'Reach Chinese level 3',target:3,value:()=>state.skills.Chinese,money:150,xp:40},
{id:'friend',title:'A familiar face',detail:'Make one close friend with a bond of 60',target:1,value:()=>Object.values(state.friends).filter(v=>v>=60).length,money:100,xp:50},
{id:'home',title:'A place of your own',detail:'Buy all three home upgrades',target:3,value:()=>['bed','kitchen','desk'].filter(id=>state.upgrades.includes(id)).length,money:300,xp:70},
{id:'founder',title:'Your first customers',detail:'Fulfil five studio orders',target:5,value:()=>state.stats.businessOrders,money:400,xp:80}
];
function dreamProgress(){const id=state.dream===''?0:+state.dream;const close=Object.values(state.friends).filter(v=>v>=60).length;if(id===1)return{done:close>=4,text:close+'/4 close friends'};if(id===2)return{done:!!state.business&&state.business.level>=3&&state.stats.businessOrders>=10,text:'Studio level '+(state.business?.level||0)+'/3 · '+state.stats.businessOrders+'/10 orders'};if(id===3)return{done:state.trips.length>=6,text:state.trips.length+'/6 cities visited'};return{done:level()>=5&&['bed','kitchen','desk'].every(id=>state.upgrades.includes(id)),text:'Player level '+level()+'/5 · '+state.upgrades.length+'/3 home upgrades'}}
function claimQuest(id){const q=quests.find(q=>q.id===id);if(!q||state.claimed.includes(id)||q.value()<q.target)return false;state.claimed.push(id);state.money+=q.money;state.xp+=q.xp;finish(q.title+' completed. Reward: ¥'+q.money+' and '+q.xp+' XP.');return true}
function claimDream(){const d=dreamProgress();if(!d.done||state.dreamClaimed)return false;state.dreamClaimed=true;state.money+=1000;state.xp+=150;finish('Dream achieved! You earned ¥1,000 and 150 XP.');return true}
function questsScreen(){const d=dreamProgress();screen('Your next chapter','Rewards can be claimed once. Follow your own pace.', '<div class="dream-card"><span class="eyebrow">YOUR DREAM</span><h3>'+dreams[state.dream===''?0:+state.dream][0]+'</h3><p>'+d.text+'</p>'+action('claimDream',state.dreamClaimed?'Dream achieved':d.done?'Claim ¥1,000 + 150 XP':'Keep building your story',state.dreamClaimed?'Reward collected':'Complete the dream to claim its reward')+'</div>'+quests.map(q=>'<div class="quest-card"><h3>'+q.title+'</h3><p>'+q.detail+'</p><progress max="'+q.target+'" value="'+Math.min(q.target,q.value())+'"></progress><span>'+Math.min(q.target,q.value())+'/'+q.target+' · ¥'+q.money+' + '+q.xp+' XP</span>'+action('quest-'+q.id,state.claimed.includes(q.id)?'Completed':q.value()>=q.target?'Claim reward':'In progress','One-time milestone')+'</div>').join(''));$('claimDream').disabled=!d.done||!!state.dreamClaimed;$('claimDream').onclick=()=>{claimDream();questsScreen()};quests.forEach(q=>{$('quest-'+q.id).disabled=state.claimed.includes(q.id)||q.value()<q.target;$('quest-'+q.id).onclick=()=>{claimQuest(q.id);questsScreen()}})}
const events=[
{title:'Language exchange at EFH',place:'ef',hour:18,cost:15,skill:'Chinese',story:'You taught someone a phrase from home and learnt two in Chinese.',options:['Join a conversation','Help a newcomer settle in']},
{title:'Campus creator challenge',place:'campus',hour:14,cost:0,skill:'Creativity',story:'Your short story about arriving in China found an audience.',options:['Share your story','Collaborate on a short video']},
{title:'Hunnan founder circle',place:'business',hour:16,cost:20,skill:'Network',story:'You met a potential client and practised introducing your idea.',options:['Pitch your studio idea','Ask for feedback']},
{title:'Basketball at Heping Gym',place:'gym',hour:17,cost:15,skill:'Fitness',story:'Your team found a rhythm. You left with an invitation to play again.',options:['Play a match','Help organise the game']},
{title:'Open mic at Foreigners’ Night',place:'night',hour:20,cost:35,skill:'Creativity',story:'The room cheered. Another small step toward feeling at home.',options:['Perform on stage','Support a new performer']},
{title:'Saturday lakeside meetup',place:'park',hour:11,cost:0,skill:'Social',story:'A walk by the lake turned into a long conversation.',options:['Join the walking group','Start a conversation']},
{title:'Market food discovery',place:'market',hour:12,cost:12,skill:'Chinese',story:'You tried something new and ordered it with confidence.',options:['Practise ordering','Learn a recipe from the vendor']}
];
function currentEvent(){const e=events[(state.day-1)%events.length],titles={ef:'Language exchange',campus:'Creator challenge',business:'Founder circle',gym:'Basketball',night:'Open mic',park:'Community meetup',market:'Food discovery'};return {...e,title:titles[e.place]+' · '+L.find(p=>p[0]===e.place)[1]}}
function attendEvent(choice){if(![0,1].includes(choice))return false;const day=state.day,e=currentEvent();if(state.eventHistory[day]!==undefined)return false;if(state.place!==e.place){toast('Travel to '+L.find(l=>l[0]===e.place)[1]+' first.');return false}if(state.hour<e.hour*60||state.hour>e.hour*60+180){toast('This event runs from '+e.hour+':00 to '+(e.hour+3)+':00.');return false}if((e.cost>0&&state.money<e.cost)||state.needs.energy<15){toast('You need ¥'+e.cost+' and at least 15 energy.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:e.place==='gym'?'basketball':e.place==='night'?'perform':'talk',x:0,z:2,label:e.title},()=>attendEvent(choice));return false}state.money-=e.cost;state.eventHistory[day]=choice;state.needs.energy-=15;state.needs.fun=Math.min(100,state.needs.fun+20);state.needs.social=Math.min(100,state.needs.social+25);gain(choice===1?'Social':e.skill,30);state.xp+=25;advance(90);finish(e.story);return true}
function eventScreen(){const e=currentEvent();const done=state.eventHistory[state.day]!==undefined;screen(e.title,'Day '+state.day+' · '+e.hour+':00–'+(e.hour+3)+':00 · '+L.find(l=>l[0]===e.place)[1]+' · ¥'+e.cost, '<p>City events rotate each game day. You can attend once per day.</p>'+action('eventTravel','Go to the venue','Choose transport on the city map')+e.options.map((o,i)=>action('eventChoice'+i,done?'Attended today':o,'90 minutes · 25 XP · skill and social boosts')).join(''));$('eventTravel').onclick=()=>{$('activityDialog').close();select(e.place)};e.options.forEach((o,i)=>{$('eventChoice'+i).disabled=done;$('eventChoice'+i).onclick=()=>{if(attendEvent(i))eventScreen()}})}
function launchBusiness(){if(state.business)return false;if(state.skills.Network<2||state.skills.Digital<2){toast('Train Network and Digital to level 2 first.');return false}if(state.money<900){toast('Opening a studio costs ¥900.');return false}state.money-=900;state.business={level:1,orders:0,revenue:0,lastOrder:0};finish('Your small creative studio is open. Your first client is waiting.');return true}
function fulfilOrder(){const b=state.business;if(!b||b.lastOrder===state.day)return false;if(state.place!=='business'){toast('Travel to Hunnan Startup Hub to fulfil the order.');return false}if(state.needs.energy<25||state.needs.hunger<20){toast('Eat and rest before taking a client order.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:'type',x:0,z:-.5,label:'Working on your client order'},()=>fulfilOrder());return false}const pay=180+b.level*90;b.lastOrder=state.day;b.orders++;b.revenue+=pay;state.stats.businessOrders++;state.money+=pay;state.needs.energy-=25;state.needs.hunger-=15;advance(180);gain('Digital',25);gain('Network',15);state.xp+=30;finish('Client order delivered. Your studio earned ¥'+pay+'.');return true}
function growBusiness(){const b=state.business;if(!b||b.level>=3)return false;const cost=b.level*1000,required=b.level*3;if(b.orders<required||state.money<cost){toast('You need '+required+' orders and ¥'+cost+' to expand.');return false}state.money-=cost;b.level++;finish('Studio expanded to level '+b.level+'. Client orders now pay more.');return true}
function businessScreen(){const b=state.business;screen(b?'Your creative studio':'Start something of your own',b?'Level '+b.level+'/3 · '+b.orders+' orders · ¥'+b.revenue+' total revenue':'Open a fictional creative studio at Hunnan. Train Network and Digital at the hub and café.',b? action('businessTravel','Go to your studio','Hunnan Startup Hub')+action('businessOrder',b.lastOrder===state.day?'Today’s order delivered':'Fulfil a client order','3 hours · earns ¥'+(180+b.level*90)+' · one order per day')+action('businessExpand',b.level===3?'Studio fully expanded':'Expand your studio','Requires '+(b.level*3)+' total orders and ¥'+(b.level*1000)):action('businessLaunch','Open your studio · ¥900','Requires Network level 2 and Digital level 2'));if(b){$('businessTravel').onclick=()=>{$('activityDialog').close();select('business')};$('businessOrder').disabled=b.lastOrder===state.day;$('businessOrder').onclick=()=>{fulfilOrder()};$('businessExpand').disabled=b.level>=3;$('businessExpand').onclick=()=>{growBusiness();businessScreen()}}else $('businessLaunch').onclick=()=>{launchBusiness();businessScreen()}}
function render(){ensure();renderBase();if(state.job){$('agenda').innerHTML='<b>Career level '+state.promotion+'/5</b><button class="soft-btn" id="workBtn">Work a shift</button>';$('workBtn').onclick=shiftScreen}if(selected==='home'){$('panelContent').insertAdjacentHTML('beforeend','<div class="panel-content"><button class="soft-btn" id="manageHome">Manage home</button></div>');$('manageHome').onclick=homeScreen}$('pulseGrid').innerHTML='<button class="pulse-card pulse-action" id="questsCard"><span class="eyebrow">YOUR GOALS</span><strong>'+quests.filter(q=>!state.claimed.includes(q.id)&&q.value()>=q.target).length+' rewards ready</strong><p>Quests, milestones and your dream.</p></button><button class="pulse-card pulse-action" id="eventCard"><span class="eyebrow">TODAY’S EVENT</span><strong>'+currentEvent().title+'</strong><p>'+currentEvent().hour+':00 · '+(state.eventHistory[state.day]!==undefined?'Attended':'Open today')+'</p></button><button class="pulse-card pulse-action" id="businessCard"><span class="eyebrow">YOUR BUSINESS</span><strong>'+(state.business?'Creative studio · Level '+state.business.level:'Start your own studio')+'</strong><p>'+(state.business?state.business.orders+' orders delivered':'Build skills and meet your first client.')+'</p></button>';$('questsCard').onclick=questsScreen;$('eventCard').onclick=eventScreen;$('businessCard').onclick=businessScreen;$('needsBtn').onclick=()=>screen('Keep your needs balanced','Activities change your needs. Rest, eat and freshen up before a shift.',needs.map(n=>'<p>'+names[n]+': '+state.needs[n]+'%</p>').join(''));$('cityBtn').onclick=tripScreen;window.dispatchEvent(new CustomEvent('chinalife:update'))}
window.ChinaLife={openCities,startOnboarding:()=>{if(!state.created){if(!$('onboarding').open)$('onboarding').showModal();onboarding()}},get accountId(){return activeAccount},setAccount:(id,{loadLocal=true}={})=>{activeAccount=id==null?null:String(id);accountName='';KEY=id?'chinalife-account-'+String(id):'chinalife-serious-v2';let stored=null;try{if(loadLocal)stored=JSON.parse(localStorage.getItem(KEY))}catch{}state=stored?.created?validateSave(stored):JSON.parse(JSON.stringify(blank));selected=state.place;step=0;studentSetupMode='create';onboard={name:'',color:'#ef9f79',trait:[],dream:'',background:''};if($('onboarding').open)$('onboarding').close();render();return state.created},get state(){return state},useAccountName:name=>{accountName=String(name||'').trim().slice(0,64);if(!accountName)return;onboard.name=accountName;if(state.created&&state.name!==accountName){state.name=accountName;save();render()}else if($('onboarding').open&&step===1)onboarding()},loadSave:v=>{const showingStory=!!$('storyNext')||!!$('storyCampus');state=validateSave(v);selected=state.place;ensure();studentSetupMode='create';if($('onboarding').open)$('onboarding').close();save();render();if(showingStory&&state.student)studentStory();else if($('activityDialog').open)$('activityDialog').close()},locations:L,cityData,catalog,shop:shopScreen,flights:airportScreen,flightQuote,cities:tripScreen,contacts,npcPeople:peopleScreen,work:shiftScreen,trips:tripScreen,activity:(id,i)=>activity(L.find(p=>p[0]===id),i),travel:select,phone,home:homeScreen,people:()=>window.ChinaLifeSocial?window.ChinaLifeSocial.open('people'):peopleScreen(),meet:id=>id.startsWith('remote:')?window.ChinaLifeSocial?.player(id.slice(7)):personScreen(id),appearance:appearanceScreen,profile:profileScreen,goals:questsScreen,event:eventScreen,business:businessScreen,wallet:walletScreen,needs:()=> $('needsBtn').onclick(),currentEvent,dreamProgress,quests,studentStory,save,refresh:render,toast,venue:(id)=>{const p=L.find(p=>p[0]===id);screen(p[1],p[6],p[7].map((a,i)=>action('venueAct'+i,a[0],a[1])).join(''));p[7].forEach((a,i)=>$('venueAct'+i).onclick=()=>activity(p,i))}};
